const watchStalledConnector = (connector: ActiveConnector) => Effect.gen(function* () {
  const broker = getNative(), pid = Number(connector.child.pid);
  while (true) {
    const active = yield* Ref.get(activeRef);
    if (active?.child.pid !== connector.child.pid || active.configKey !== connector.configKey) return;
    const reset = broker.connectorRecovery.observe(pid, broker.tunnelHealth.isConnected(pid), yield* Clock.currentTimeMillis);
    if (reset) {
      yield* reconcileSemaphore.withPermits(1)(Effect.gen(function* () {
        const current = yield* Ref.get(activeRef), desired = yield* Ref.get(desiredConfigRef);
        if (current?.child.pid !== connector.child.pid || current.configKey !== connector.configKey ||
          !desired || runtimeConfigKey(desired) !== connector.configKey || broker.tunnelHealth.isConnected(pid)) return;
        if (!(yield* connector.child.isRunning.pipe(Effect.orElseSucceed(() => false)))) return;
        broker.connectionDiagnostics.record("tunnel-recovery", { reason: "all-edges-stalled-local-restart" });
        locallyRestarted.add(pid);
        yield* connector.child.kill({ forceKillAfter: "5 seconds" }).pipe(Effect.catch(() => Effect.sync(() => {
          locallyRestarted.delete(pid);
          broker.connectionDiagnostics.record("tunnel-recovery", { reason: "local-restart-failed" });
        })));
      }));
      return;
    }
    yield* Effect.sleep(Duration.millis(broker.connectorRecovery.pollIntervalMs));
  }
}).pipe(Effect.catchCause((cause) => Cause.hasInterrupts(cause) ? Effect.interrupt : Effect.sync(() =>
  getNative().connectionDiagnostics.record("tunnel-recovery", { reason: "watchdog-failed" }))));

