Layer.succeed(RpcScopeAuthorization)((effect, { rpc, payload }) => {
  const requiredScope = requiredScopeForRpcMethod(rpc._tag);
  const allowed = PiNative.rpcAllowed(rpc._tag);
  const authorized = scopes.includes(requiredScope);
  const command = rpc._tag === "orchestration.dispatchCommand" ? (payload as any) : undefined;
  return observeNativeRpc(rpc._tag,
    allowed && authorized ? effect : Effect.fail(rpcAuthorizationError(requiredScope)),
    {
      "orchestration_v2.command_id": command?.commandId,
      "orchestration_v2.command_type": command?.type,
      "orchestration_v2.thread_id": command?.threadId,
      "pimac.dispatch_mode": command?.type === "message.dispatch" ? command.dispatchMode?.type : undefined,
      "pimac.delivery_intent": command?.type === "message.dispatch" ? command.deliveryIntent : undefined,
    }, { allowed, authorized });
});
